    /*
     * Add to the Observations
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	LabResult
     */
    public LabResult addToObservations( UUID parentId, Observation addTo ) {
	    LOGGER.info("handling AssignObservationsToLabResultEvent - " );
	    
	    LabResult parentEntity = repository.findById(parentId).get();
	    Observation child = registry.project( Observation.class, addTo.getObservationId());
	    
	    parentEntity.getObservations().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Observations
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	LabResult
     */
	public LabResult removeFromObservations( UUID parentId, Observation removeFrom ) {
	    LOGGER.info("handling RemoveObservationsFromLabResultEvent " );
	
	    LabResult parentEntity = repository.findById(parentId).get();
	    Observation child = registry.project( Observation.class, removeFrom.getObservationId());
	    
	    parentEntity.getObservations().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



